# BFS distances over all 7 cells (cols>=1), inspect distance at new markers and local maxima
from collections import deque
def bfs7(A,s):
 H,W=A.shape; dist={s:0};q=deque([s])
 while q:
  x,y=q.popleft()
  for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
   p=(x+dx,y+dy)
   if 0<=p[0]<H and 1<=p[1]<W and A[p]==7 and p not in dist:
    dist[p]=dist[(x,y)]+1;q.append(p)
 return dist
